    int bit;
    if (code < bound) { range = bound; *p = (CLzmaProb)(prob + ((2048 - prob) >> 5)); bit = 0; }
    else { range -= bound; code -= bound; *p = (CLzmaProb)(prob - (prob >> 5)); bit = 1; }
    Normalize();
    return bit;
  }
