typedef uint32_t UInt32; typedef uint64_t UInt64; typedef uint8_t Byte; typedef uint16_t CLzmaProb;
struct Enc {
  Byte *out; size_t outPos,outCap;
  UInt64 low; UInt32 range; Byte cache; int cacheSize;
  int lc,lp,pb,lcOff, shMask, csInit, cfInit, finMask, dbConv;
  CLzmaProb *probs; unsigned state;
  inline void PutByte(Byte b){ if(outPos<outCap) out[outPos++]=b; else outPos++; }
  inline void ShiftLow(){
    if ((UInt32)low < (UInt32)0xFF000000 || (int)(low >> 32) != 0) {
      Byte temp=cache;
      do { PutByte((Byte)(temp + (Byte)(low >> 32))); temp = 0xFF; } while (--cacheSize);
      if (shMask&1) cache=(Byte)(low>>24);
    }
