    Norm();
  }
  inline void EncBT(CLzmaProb*p,unsigned sym,int nbits){
    unsigned i=1u<<nbits;
    do { i>>=1; EncBit(p+(sym+i), (sym&i)?1:0); } while(i>1);
  }
