// minimal LZMA literal-only encoder, validates range coder + literal probs layout
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
typedef uint32_t UInt32; typedef uint64_t UInt64; typedef uint8_t Byte; typedef uint16_t CLzmaProb;
struct Enc {
  Byte *out; size_t outPos,outCap;
  UInt64 low; UInt32 range;
  Byte pend[64]; int pendN;
  int lc,lp,pb,lcOff;
  CLzmaProb *probs; unsigned state;
  inline void PutByte(Byte b){ if(outPos<outCap) out[outPos++]=b; else outPos++; }
  inline void ShiftLow(){
    Byte top=(Byte)(low>>24);
    int carry=(int)(low>>32);
    if (top!=0xFF || carry) {
      // apply carry from newest backwards
      for (int i=pendN-1;i>=0;i--){
        int v=pend[i]+carry;
        if (v>0xFF){ pend[i]=0; carry=1; } else { pend[i]=(Byte)v; carry=0; }
      }
      for (int i=0;i<pendN;i++) PutByte(pend[i]);
      pendN=0; pend[pendN++]=top;
    }
    low=(low<<8)&0xFFFFFFFFULL;
  }
  inline void Norm(){ while(range<((UInt32)1<<24)){ range<<=8; ShiftLow(); } }
  inline void EncBit(CLzmaProb*p,int bit){
    UInt32 prob=*p, bound=(range>>11)*prob;
    if (bit==0){ range=bound; *p=(CLzmaProb)(prob+((2048-prob)>>5)); }
    else { low+=bound; range-=bound; *p=(CLzmaProb)(prob-(prob>>5)); }
    Norm();
  }
  inline void EncBT(CLzmaProb*p,unsigned sym,int nbits){
    unsigned m=1;
    for(int i=nbits-1;i>=0;i--){ unsigned bit=(sym>>i)&1; EncBit(p+m,bit); m=(m<<1)+bit; }
  }
  void Init(const Byte*,size_t,int lcx,int lpx,int pbx,int lcOff_,Byte*o,size_t oc){
    out=o; outPos=0; outCap=oc; low=0; range=0xFFFFFFFF; pendN=1; pend[0]=0;
    lc=lcx;lp=lpx;pb=pbx;lcOff=lcOff_; state=0;
    unsigned num=(0x400<<(lc+lp))+4000; probs=(CLzmaProb*)malloc(num*sizeof(CLzmaProb));
    for(unsigned i=0;i<num;i++) probs[i]=1024;
  }
  void EncLiterals(const Byte*d,size_t n){
    for(size_t i=0;i<n;i++){
      unsigned litCtx=((unsigned)(i&((1u<<lp)-1))<<lc)|(i?(d[i-1]>>(8-lc)):0);
      CLzmaProb*p=probs+0x300*litCtx;
      EncBT(p,d[i],8);
    }
  }
  void Finish(){
    low += range-1;
    for(int i=0;i<5;i++) ShiftLow();
  }
};
int main(int argc,char**argv){
  FILE*f=fopen(argv[1],"rb"); fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
  Byte*d=(Byte*)malloc(n); if(fread(d,1,n,f)!=(size_t)n){} fclose(f);
  int lcOff=atoi(argv[2]);
  Byte*o=(Byte*)malloc(n*3+1024);
  Enc e; e.Init(d,n,3,0,2,lcOff,o,n*3+1024);
  o[0]=93;o[1]=0;o[2]=0;o[3]=0x80;o[4]=0; for(int i=0;i<8;i++) o[5+i]=0xFF;
  e.outPos=13;
  e.EncLiterals(d,n);
  e.Finish();
  FILE*of=fopen(argv[3],"wb"); fwrite(o,1,e.outPos,of); fclose(of);
  printf("wrote %zu\n",e.outPos);
  return 0;
}
EOF
