```
EncodeBit(probs, idx, bit):
  prob = probs[idx]
  bound = (range >> 11) * prob
  if bit==0: range = bound; prob += (2048-prob)>>5
  else: low += bound; range -= bound; prob -= prob>>5
  probs[idx] = prob
  normalize

EncodeTree(probs, numBits, sym):  // MSB first
  m = 1
  for i = numBits-1 .. 0:
    bit = (sym >> i) & 1
    EncodeBit(probs, m, bit)
    m = (m<<1) + bit

EncodeReverseTree(probs, numBits, sym):  // LSB first
  m = 1
  for i = 0 .. numBits-1:
    bit = (sym >> i) & 1
    EncodeBit(probs, m, bit)
    m = (m<<1) + bit
```

