  CLzmaProb *probs; unsigned state;
  inline Byte NB(){ return inPos<inLim? in[inPos++] : 0; }
  inline void Norm(){ if (range<((UInt32)1<<24)) { code=(code<<8)|NB(); range<<=8; } }
