    else { range-=b; code-=b; *p=(CLzmaProb)(prob-(prob>>5)); bit=1; }
    Norm(); return bit; }
  unsigned BT(CLzmaProb*p,int n){ unsigned m=1; for(int i=0;i<n;i++) m=(m<<1)+DBit(p+m); return m-(1u<<n); }
  void Init(const Byte*d,size_t n){ in=d; inPos=0; inLim=n; range=0xFFFFFFFF; code=0; for(int i=0;i<5;i++) code=(code<<8)|NB();
