  void Init(Byte*o,size_t oc,int v){ out=o; outPos=0; outCap=oc; low=0; range=0xFFFFFFFF; pendN=0; variant=v;
    probs=(CLzmaProb*)malloc(0x400*sizeof(CLzmaProb)); for(int i=0;i<0x400;i++) probs[i]=1024; }
  void EncLit(Byte b){ EncBT(probs,b,8); }
  void Finish(){ low += range-1; for(int i=0;i<5;i++) ShiftLow(); }
};
int main(int argc,char**argv){
  FILE*f=fopen(argv[1],"rb"); fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
  Byte*d=(Byte*)malloc(n); if(fread(d,1,n,f)!=(size_t)n){} fclose(f);
  Byte*o=(Byte*)malloc(n*3+1024);
  for(int v=0;v<4;v++){
    Enc e; e.Init(o,n*3+1024,v);
    for(long i=0;i<n;i++) e.EncLit(d[i]);
    e.Finish();
    printf("v%d enc %zu bytes: ",v,e.outPos);
    Dec dec; dec.Init(o,e.outPos);
    int ok=1;
    for(long i=0;i<n;i++){ Byte b=dec.Lit(); if (b!=d[i]) { printf("RT-MISMATCH@%ld",i); ok=0; break; } }
    if (ok) printf("RT-OK");
    printf("\n");
    char nm[64]; sprintf(nm,"/tmp/rt_%d.bin",v);
    FILE*of=fopen(nm,"wb"); fwrite(o,1,e.outPos,of); fclose(of);
  }
  return 0;
}
